def retry_schedule(initial: int, maximum: int, attempts: int) -> list[int] | None:
    if any(type(x) is not int for x in (initial,maximum,attempts)) or initial<0 or initial>maximum or attempts<0:return None
    out=[];delay=initial
    for _ in range(attempts):out.append(delay);delay=min(maximum,delay*2)
    return out
